const { Given, When, Then } = require('@cucumber/cucumber');

// ---------------------------------------------------------------------------
// Given
// ---------------------------------------------------------------------------

Given('the app is loaded', function () {
  // Already loaded by Before hook in world.js; nothing to do.
});

Given('the todo list is empty', function () {
  // No pre-existing todos; state is already clean after loadApp().
});

Given('the user has added todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Given('the user has added completed todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true }));
  const toggle = this.getTodoToggle(title);
  if (toggle && !toggle.checked) {
    toggle.click();
  }
});

// ---------------------------------------------------------------------------
// When
// ---------------------------------------------------------------------------

When('the user types {string} into the new-todo input and presses Enter', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user presses Enter without typing anything', function () {
  const input = this.document.querySelector('.new-todo');
  input.value = '';
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user toggles the checkbox for todo {string}', function (title) {
  const toggle = this.getTodoToggle(title);
  if (!toggle) throw new Error(`No toggle found for todo "${title}"`);
  toggle.click();
});

When('the user toggles the Mark all as complete checkbox', function () {
  const checkbox = this.document.querySelector('#toggle-all');
  checkbox.click();
});

When('the user double-clicks the label for todo {string}', function (title) {
  const label = this.getTodoLabel(title);
  if (!label) throw new Error(`No label found for todo "${title}"`);
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('the user types {string} into the edit input and presses Enter', function (title) {
  const edit = this.getEditingInput();
  if (!edit) throw new Error('No editing input found');
  edit.value = title;
  edit.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user types {string} into the edit input and blurs', function (title) {
  const edit = this.getEditingInput();
  if (!edit) throw new Error('No editing input found');
  edit.value = title;
  edit.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  edit.dispatchEvent(new this.window.Event('focusout', { bubbles: true }));
  edit.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('the user clears the edit input and presses Enter', function () {
  const edit = this.getEditingInput();
  if (!edit) throw new Error('No editing input found');
  edit.value = '';
  edit.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user types {string} into the edit input and presses Escape', function (title) {
  const edit = this.getEditingInput();
  if (!edit) throw new Error('No editing input found');
  edit.value = title;
  edit.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Escape', keyCode: 27, bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Escape', keyCode: 27, bubbles: true }));
});

When('the user clicks the destroy button for todo {string}', function (title) {
  const destroy = this.getTodoDestroy(title);
  if (!destroy) throw new Error(`No destroy button found for todo "${title}"`);
  destroy.click();
});

When('the user clicks the Clear completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  btn.click();
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

When('the app is reloaded', function () {
  // Capture current todos from the live window's localStorage before disposing.
  const saved = this.loadTodosFromStorage();
  this.disposeApp();
  this.loadApp();
  // Restore the saved todos into the fresh window's localStorage, then trigger
  // hashchange to force the app's render() cycle so it picks up the stored data.
  this.restoreTodosToStorage(saved);
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

// ---------------------------------------------------------------------------
// Then
// ---------------------------------------------------------------------------

Then('a todo {string} appears in the list', function (title) {
  const labels = Array.from(this.document.querySelectorAll('.todo-list .view label'));
  const found = labels.some(el => el.textContent === title);
  if (!found) throw new Error(`Expected todo "${title}" in list, not found. Labels: ${labels.map(l => l.textContent).join(', ')}`);
});

Then('the new-todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  if (input.value !== '') throw new Error(`Expected new-todo input empty, got "${input.value}"`);
});

Then('the item count shows {string}', function (text) {
  const strong = this.document.querySelector('.todo-count strong');
  const parent = this.document.querySelector('.todo-count');
  const actual = parent.textContent.trim();
  if (actual !== text) throw new Error(`Expected item count "${text}", got "${actual}"`);
});

Then('no todo is added to the list', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length > 0) {
    throw new Error(`Expected empty list, found ${items.length} items`);
  }
});

Then('todo {string} is marked as completed', function (title) {
  const li = this.getTodoLi(title);
  if (!li) throw new Error(`No todo found for "${title}"`);
  if (!li.classList.contains('completed')) throw new Error(`Todo "${title}" is not marked completed`);
  const toggle = this.getTodoToggle(title);
  if (!toggle.checked) throw new Error(`Todo "${title}" checkbox is not checked`);
});

Then('todo {string} is not marked as completed', function (title) {
  const li = this.getTodoLi(title);
  if (!li) throw new Error(`No todo found for "${title}"`);
  if (li.classList.contains('completed')) throw new Error(`Todo "${title}" is still marked completed`);
  const toggle = this.getTodoToggle(title);
  if (toggle.checked) throw new Error(`Todo "${title}" checkbox is still checked`);
});

Then('all todos are marked as completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    if (!li.classList.contains('completed')) throw new Error(`Todo not completed: ${li.querySelector('label').textContent}`);
  }
});

Then('no todo is marked as completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    if (li.classList.contains('completed')) throw new Error(`Todo still completed: ${li.querySelector('label').textContent}`);
  }
});

Then('the Mark all as complete checkbox is not checked', function () {
  const checkbox = this.document.querySelector('#toggle-all');
  if (checkbox.checked) throw new Error('Mark all checkbox is checked but expected unchecked');
});

Then('the Mark all as complete checkbox is checked', function () {
  const checkbox = this.document.querySelector('#toggle-all');
  if (!checkbox.checked) throw new Error('Mark all checkbox is unchecked but expected checked');
});

Then('todo {string} is in editing mode', function (title) {
  const li = this.getTodoLi(title);
  if (!li) throw new Error(`No todo found for "${title}"`);
  if (!li.classList.contains('editing')) throw new Error(`Todo "${title}" is not in editing mode`);
  const edit = li.querySelector('.edit');
  if (this.document.activeElement !== edit && !edit.matches(':focus')) {
    throw new Error(`Edit input for "${title}" is not focused`);
  }
});

Then('todo {string} is not in editing mode', function (title) {
  const li = this.getTodoLi(title);
  if (!li) throw new Error(`No todo found for "${title}"`);
  if (li.classList.contains('editing')) throw new Error(`Todo "${title}" is still in editing mode`);
});

Then('no todo {string} exists', function (title) {
  const labels = Array.from(this.document.querySelectorAll('.todo-list .view label'));
  const found = labels.some(el => el.textContent === title);
  if (found) throw new Error(`Todo "${title}" should not exist but was found`);
});

Then('the Clear completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  const style = this.window.getComputedStyle(btn);
  if (style.display !== 'none' && btn.offsetParent !== null) {
    throw new Error('Clear completed button is visible but expected hidden');
  }
});

Then('no todo {string} appears in the list', function (title) {
  const labels = Array.from(this.document.querySelectorAll('.todo-list .view label'));
  const found = labels.some(el => el.textContent === title);
  if (found) throw new Error(`Todo "${title}" should not appear in list but was found`);
});

Then('the {string} filter link is selected', function (filterName) {
  const links = this.document.querySelectorAll('.filters a');
  const link = Array.from(links).find(a => a.textContent === filterName);
  if (!link) throw new Error(`Filter link "${filterName}" not found`);
  if (!link.classList.contains('selected')) throw new Error(`Filter link "${filterName}" is not selected`);
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  if (style.display !== 'none' && main.offsetParent !== null) {
    throw new Error('Main section is visible but expected hidden');
  }
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  if (style.display !== 'none' && footer.offsetParent !== null) {
    throw new Error('Footer is visible but expected hidden');
  }
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  if (style.display === 'none') {
    throw new Error('Main section is hidden but expected visible');
  }
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  if (style.display === 'none') {
    throw new Error('Footer is hidden but expected visible');
  }
});

When('the user captures the todo list item for {string}', function (title) {
  // Store a live DOM reference so a later step can verify the element
  // was not destroyed and recreated by a re-render.
  const li = this.getTodoLi(title);
  if (!li) throw new Error(`No todo found for "${title}"`);
  this._capturedTodoLi = li;
});

Then('the captured todo list item is still attached to the DOM', function () {
  if (!this._capturedTodoLi) {
    throw new Error('No todo list item was captured by a preceding capture step');
  }
  if (!this.document.body.contains(this._capturedTodoLi)) {
    throw new Error(
      'The captured todo list item was detached from the DOM after re-render. ' +
      'The app destroyed and recreated DOM nodes instead of updating them in place. ' +
      'This breaks browser automation tools that hold element references across actions.'
    );
  }
  delete this._capturedTodoLi;
});

/* global */
(function () {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;

	var storageKey = 'todos-todomvc';

	// ---- Storage helpers ----

	function loadTodos() {
		try {
			return JSON.parse(localStorage.getItem(storageKey)) || [];
		} catch (e) {
			return [];
		}
	}

	function saveTodos(todos) {
		localStorage.setItem(storageKey, JSON.stringify(todos));
	}

	// ---- State ----

	var todos = loadTodos();
	var currentFilter = getFilterFromHash();

	function getFilterFromHash() {
		var hash = window.location.hash || '#/';
		if (hash === '#/active') return 'active';
		if (hash === '#/completed') return 'completed';
		return 'all';
	}

	// ---- DOM references ----

	var todoList = document.querySelector('.todo-list');
	var newTodoInput = document.querySelector('.new-todo');
	var toggleAllCheckbox = document.querySelector('#toggle-all');
	var clearCompletedBtn = document.querySelector('.clear-completed');
	var todoCountEl = document.querySelector('.todo-count');
	var filterLinks = document.querySelectorAll('.filters a');
	var mainSection = document.querySelector('.main');
	var footerSection = document.querySelector('.footer');

	// ---- Rendering ----

	function render() {
		var filtered = todos.filter(function (t) {
			if (currentFilter === 'active') return !t.completed;
			if (currentFilter === 'completed') return t.completed;
			return true;
		});

		todoList.innerHTML = '';
		filtered.forEach(function (todo) {
			var li = document.createElement('li');
			li.setAttribute('data-id', todo.id);

			if (todo.completed) li.classList.add('completed');

			li.innerHTML =
				'<div class="view">' +
					'<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
					'<label>' + escapeHtml(todo.title) + '</label>' +
					'<button class="destroy"></button>' +
				'</div>' +
				'<input class="edit" value="' + escapeHtml(todo.title) + '">';

			todoList.appendChild(li);
		});

		var activeCount = todos.filter(function (t) { return !t.completed; }).length;
		var completedCount = todos.filter(function (t) { return t.completed; }).length;
		var countText = activeCount + (activeCount === 1 ? ' item' : ' items') + ' left';
		todoCountEl.innerHTML = '<strong>' + activeCount + '</strong> ' + countText.split(' ').slice(1).join(' ');

		toggleAllCheckbox.checked = todos.length > 0 && activeCount === 0;

		if (todos.length === 0) {
			mainSection.style.display = 'none';
			footerSection.style.display = 'none';
		} else {
			mainSection.style.display = '';
			footerSection.style.display = '';
		}

		clearCompletedBtn.style.display = completedCount > 0 ? '' : 'none';

		filterLinks.forEach(function (link) {
			link.classList.remove('selected');
		});
		filterLinks.forEach(function (link) {
			if (link.getAttribute('href') === '#/' + (currentFilter === 'all' ? '' : currentFilter)) {
				link.classList.add('selected');
			}
		});
	}

	function escapeHtml(text) {
		var div = document.createElement('div');
		div.appendChild(document.createTextNode(text));
		return div.innerHTML;
	}

	function nextId() {
		return todos.length ? Math.max.apply(null, todos.map(function (t) { return t.id; })) + 1 : 1;
	}

	/** @planks("the user types {string} into the new-todo input and presses Enter") */
	function addTodo(title) {
		title = title.trim();
		if (!title) return;
		todos.push({ id: nextId(), title: title, completed: false });
		saveTodos(todos);
		render();
	}

	/** @planks("the user clicks the destroy button for todo {string}") */
	function removeTodo(id) {
		todos = todos.filter(function (t) { return t.id !== id; });
		saveTodos(todos);
		render();
	}

	/** @planks("the user toggles the checkbox for todo {string}") */
	function toggleTodo(id) {
		todos.forEach(function (t) {
			if (t.id === id) t.completed = !t.completed;
		});
		saveTodos(todos);
		render();
	}

	/** @planks("the user toggles the Mark all as complete checkbox") */
	function toggleAll() {
		var allCompleted = todos.every(function (t) { return t.completed; });
		todos.forEach(function (t) { t.completed = !allCompleted; });
		saveTodos(todos);
		render();
	}

	/** @planks("the user clicks the Clear completed button") */
	function clearCompleted() {
		todos = todos.filter(function (t) { return !t.completed; });
		saveTodos(todos);
		render();
	}

	function findTodoById(id) {
		for (var i = 0; i < todos.length; i++) {
			if (todos[i].id === id) return todos[i];
		}
		return null;
	}

	/** @planks("the user double-clicks the label for todo {string}") */
	function startEditing(li) {
		li.classList.add('editing');
		var editInput = li.querySelector('.edit');
		editInput.value = findTodoById(parseInt(li.getAttribute('data-id'), 10)).title;
		editInput.focus();
	}

	/** @planks("the user types {string} into the edit input and presses Enter") */
	function saveEdit(li) {
		var id = parseInt(li.getAttribute('data-id'), 10);
		var editInput = li.querySelector('.edit');
		var title = editInput.value.trim();
		if (title === '') {
			removeTodo(id);
		} else {
			var todo = findTodoById(id);
			if (todo) {
				todo.title = title;
				saveTodos(todos);
				render();
			}
		}
	}

	/** @planks("the user types {string} into the edit input and presses Escape") */
	function cancelEdit(li) {
		li.classList.remove('editing');
		var id = parseInt(li.getAttribute('data-id'), 10);
		var todo = findTodoById(id);
		if (todo) {
			li.querySelector('.edit').value = todo.title;
		}
	}

	// ---- Event handlers ----

	newTodoInput.addEventListener('keydown', function (e) {
		if (e.keyCode === ENTER_KEY) {
			e.preventDefault();
			addTodo(newTodoInput.value);
			newTodoInput.value = '';
		}
	});

	todoList.addEventListener('click', function (e) {
		var target = e.target;
		var li = target.closest('li');
		if (!li) return;
		var id = parseInt(li.getAttribute('data-id'), 10);

		if (target.classList.contains('toggle')) {
			toggleTodo(id);
		} else if (target.classList.contains('destroy')) {
			removeTodo(id);
		}
	});

	todoList.addEventListener('dblclick', function (e) {
		var target = e.target;
		if (target.tagName.toLowerCase() !== 'label') return;
		var li = target.closest('li');
		if (!li) return;
		startEditing(li);
	});

	todoList.addEventListener('keydown', function (e) {
		var target = e.target;
		if (!target.classList.contains('edit')) return;
		var li = target.closest('li');
		if (!li) return;

		if (e.keyCode === ENTER_KEY) {
			e.preventDefault();
			saveEdit(li);
		} else if (e.keyCode === ESCAPE_KEY) {
			cancelEdit(li);
		}
	});

	todoList.addEventListener('focusout', function (e) {
		var target = e.target;
		if (!target.classList.contains('edit')) return;
		var li = target.closest('li');
		if (!li) return;
		if (li.classList.contains('editing')) {
			saveEdit(li);
		}
	});

	toggleAllCheckbox.addEventListener('change', function () {
		toggleAll();
	});

	clearCompletedBtn.addEventListener('click', function () {
		clearCompleted();
	});

	filterLinks.forEach(function (link) {
		link.addEventListener('click', function (e) {
			e.preventDefault();
			var href = link.getAttribute('href');
			if (window.location.hash !== href) {
				window.location.hash = href;
			}
		});
	});

	window.addEventListener('hashchange', function () {
		todos = loadTodos();
		currentFilter = getFilterFromHash();
		render();
	});

	// ---- Init ----

	render();
})();

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // --- helpers for step definitions ---

  getTodoLi(title) {
    const labels = this.document.querySelectorAll('.todo-list .view label');
    for (const label of labels) {
      if (label.textContent === title) return label.closest('li');
    }
    return null;
  }

  getTodoToggle(title) {
    const li = this.getTodoLi(title);
    return li ? li.querySelector('.toggle') : null;
  }

  getTodoLabel(title) {
    const li = this.getTodoLi(title);
    return li ? li.querySelector('.view label') : null;
  }

  getTodoDestroy(title) {
    const li = this.getTodoLi(title);
    return li ? li.querySelector('.destroy') : null;
  }

  getEditingInput() {
    const editing = this.document.querySelector('.todo-list li.editing');
    return editing ? editing.querySelector('.edit') : null;
  }

  loadTodosFromStorage() {
    const raw = this.window.localStorage.getItem('todos-todomvc');
    return raw ? JSON.parse(raw) : [];
  }

  restoreTodosToStorage(todos) {
    this.window.localStorage.setItem('todos-todomvc', JSON.stringify(todos));
  }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

